package com.yuegang.zhihui.search.application;
import static org.assertj.core.api.Assertions.*;import java.lang.reflect.Method;import java.sql.Timestamp;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class HybridSearchMetadataBranchesTest{
 @Test void parsesEverySupportedOptionalMetadataRepresentation()throws Exception{OffsetDateTime now=OffsetDateTime.parse("2026-07-12T12:00:00Z");assertThat(((Number)call("number",Object.class,7)).intValue()).isEqualTo(7);assertThat(((Number)call("number",Object.class,"bad")).intValue()).isZero();assertThat(call("date",Object.class,now.toString())).isEqualTo(now);assertThat(call("date",Object.class,"")).isNull();assertThat(call("date",Object.class,"invalid")).isNull();assertThat(call("offset",Object.class,now)).isSameAs(now);assertThat(call("offset",Object.class,Timestamp.valueOf(now.toLocalDateTime()))).isNotNull();assertThat(call("offset",Object.class,now.toString())).isEqualTo(now);assertThat(call("excerpt",String.class,"short")).isEqualTo("short");assertThat((String)call("excerpt",String.class,"x".repeat(301))).hasSize(300);assertThat((List<?>)call("parse",Map.class,null)).isEmpty();assertThat((List<?>)call("parse",Map.class,Map.of())).isEmpty();assertThat((List<?>)call("parse",Map.class,Map.of("hits",Map.of()))).isEmpty();}
 private static Object call(String name,Class<?>type,Object value)throws Exception{Method method=HybridSearchService.class.getDeclaredMethod(name,type);method.setAccessible(true);return method.invoke(null,value);}
}
